/***
 * MARK: runHarnessStage
 * @description Runs one stage through any HarnessSession-conforming harness
 *   (ADR 0009 step 3 execution). Subscribes first so no frame is missed,
 *   forwards text deltas (`assistant_delta.delta`, `harness_log.text`) to
 *   `onLog` in order, and EVERY normalized session event to `onEvent`
 *   (structured transport: tool calls/results, thinking, usage, permissions,
 *   plans, errors). The `onLog` derivation is byte-identical to the
 *   pre-structured behavior so existing callers are unaffected. Disposes the
 *   session even when prompting throws.
 * @example await runHarnessStage({ harness, prompt: 'do X', onLog: () => {} }) => { output: '...' }
 * @param {Object} opts - Options.
 * @param {Object} opts.harness - Harness with `createSession(project, meta)`.
 * @param {Object} opts.project - Project entity passed to createSession.
 * @param {string} opts.workdir - Stage working directory (passed via meta).
 * @param {string} opts.taskId - Task id (session meta).
 * @param {string} opts.stageId - Stage id (session meta).
 * @param {string} [opts.model] - Model pin (session meta).
 * @param {string} opts.prompt - Stage prompt text.
 * @param {Function} [opts.onLog] - Called with each log string, in order.
 * @param {Function} [opts.onEvent] - Called with each normalized session event, in order.
 * @param {Function} [opts.onSession] - Called with the live session after creation (steering delivery, WP-3.4).
 * @returns {Promise<Object>} `{ output }` — the final assistant text.
 ***/
export async function runHarnessStage({
	harness,
	project,
	workdir,
	taskId,
	stageId,
	model = "",
	prompt,
	onLog = () => {},
	onEvent = null,
	onSession = null,
}) {
	if (!harness || typeof harness.createSession !== "function") {
		throw new Error("runHarnessStage needs a harness with createSession.");
	}
	if (typeof prompt !== "string" || !prompt) {
		throw new Error("runHarnessStage needs a prompt string.");
	}
	const session = await harness.createSession(project, {
		taskId,
		stageId,
		sessionDir: workdir,
		...(model ? { model } : {}),
	});
	if (typeof onSession === "function") {
		try {
			onSession(session);
		} catch {
			// Observer only: a throwing hook must never break the run.
		}
	}
	const seen = new Set();
	const unsubscribe = session.subscribe((event) => {
		if (!event || typeof event !== "object") return;
		// Structured transport first: every normalized event reaches onEvent
		// in subscription order. A throwing observer must never break the
		// run (same observer-only contract as onSession below).
		if (typeof onEvent === "function") {
			try {
				onEvent(event);
			} catch {
				// Observer only: a throwing hook must never break the run.
			}
		}
		if (event.type === "assistant_delta" && typeof event.delta === "string" && !seen.has(event)) {
			seen.add(event);
			onLog(event.delta);
		} else if (event.type === "harness_log" && typeof event.text === "string" && !seen.has(event)) {
			seen.add(event);
			onLog(event.text);
		}
	});
	try {
		const output = await session.prompt(prompt);
		if (typeof session.getLastAssistantText === "function") {
			const last = session.getLastAssistantText();
			if (typeof last === "string" && last) return { output: last };
		}
		return { output: typeof output === "string" ? output : "" };
	} catch (err) {
		// Mark prompt-phase throws as stage failures: the backend's
		// routeStageError classifies them (infrastructure vs stage failure),
		// mirroring the embedded engine's catch around the same call.
		if (err && typeof err === "object") {
			err.failedOutcome = err?.message || String(err);
		}
		throw err;
	} finally {
		if (typeof unsubscribe === "function") unsubscribe();
		if (typeof session.dispose === "function") await session.dispose();
	}
}

import { execFile, spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import { listOrphanWorkdirs, prepareIntegrationWorkdir, prepareWorkdir, reapTaskWorkdirIfTerminal, removeIntegrationWorkdir, runGit, slugForRepo, syncTaskDocs, touchWorkdir } from "./project.js";
import { RunnerGitError } from "./project.js";
import { runHarnessStage } from "./harness.js";
import { createStructuredEventSender } from "./logEvents.js";
import { applyUpdate as defaultApplyUpdate, checkForUpdate as defaultCheckForUpdate } from "./updates/index.js";
import { defaultInstallRoot, markUpdateSuccess, readUpdateState } from "./updates/state.js";
// The Runner bundle ships shared/ next to this folder (runner/{runner,api,shared}
// in prod and in the distributable tarball), so ../shared resolves both in the
// repo and in every deployed layout — the same copy the backend executes.
import { discoverClaudeModels, resolveAdvertisedModels } from "./modelDiscovery.js";
import { servingModelFor } from "../shared/servingModelFor.js";
import { formatPosture } from "../shared/formatPosture.js";
import { commitAndPush } from "./gitOps.js";

/***
 * MARK: RUNNER_VERSION
 * @description Runner product version (the update channel + fleet matrix
 *   compare this, not the API version). Loaded from runner/version.json
 *   `runnerVersion` beside daemon.js; falls back to the pinned fallback
 *   when the file is unreadable. The release packager stamps version.json
 *   per release, so a self-updated Runner re-registers as the new version.
 * @example RUNNER_VERSION => '0.1.0'
 ***/
export const RUNNER_VERSION = (() => {
	try {
		const file = new URL("./version.json", import.meta.url);
		const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
		return typeof parsed?.runnerVersion === "string" && parsed.runnerVersion ? parsed.runnerVersion : "0.1.0";
	} catch {
		return "0.1.0";
	}
})();

/***
 * MARK: RUNNER_API_VERSION
 * @description Backend API version this Runner speaks, loaded from
 *   runner/version.json at startup (kept beside daemon.js in the bundle).
 *   Falls back to the pinned fallback when the file is unreadable; the test
 *   suite pins the fallback to runner/version.json.
 * @example RUNNER_API_VERSION => '1.0.0'
 ***/
export const RUNNER_API_VERSION = (() => {
	try {
		const file = new URL("./version.json", import.meta.url);
		const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
		return typeof parsed?.apiVersion === "string" && parsed.apiVersion ? parsed.apiVersion : "1.0.0";
	} catch {
		return "1.0.0";
	}
})();

// Claim renewal cadence: comfortably inside the 5-minute production lease
// TTL (KAINBAIN_CLAIM_TTL_MS) so long harness runs keep their fence. A
// shorter operator TTL still heals via lazy expiry + STALE_EPOCH fencing.
export const CLAIM_HEARTBEAT_MS = 60_000;

const execFileAsync = promisify(execFile);

/***
 * MARK: HARNESS_VERSION_BINS
 * @description CLI binaries probed for `--version` per harness id (G5:
 *   R07/R11 version drift). First binary that answers wins; `mock` has no
 *   CLI and reports a fixed marker. Probing is best-effort with a short
 *   timeout — a missing CLI resolves to "unknown", never a boot failure.
 * @example HARNESS_VERSION_BINS.vibe => ['vibe']
 ***/
export const HARNESS_VERSION_BINS = {
	mock: [],
	pi: ["pi"],
	muse: ["muse"],
	antigravity: ["agy", "antigravity"],
	vibe: ["vibe"],
};

const harnessVersionCache = new Map();

/***
 * MARK: probeHarnessVersions
 * @description Probes the harness CLI's `--version` once per process and
 *   caches it (G5). Returns `{ [harnessId]: version }` for `factsFor`, so
 *   the backend capability record names the real CLI drift instead of
 *   "unknown". Unknown ids and missing/slow CLIs resolve to "unknown".
 * @example await probeHarnessVersions('mock') => { mock: 'mock' }
 * @param {string} harnessId - Harness id (mock, pi, muse, antigravity, vibe).
 * @param {Object} [opts] - Options.
 * @param {number} [opts.timeoutMs=4000] - Per-binary probe timeout.
 * @returns {Promise<Object>} Version map for `factsFor`.
 ***/
export async function probeHarnessVersions(harnessId, { timeoutMs = 4000 } = {}) {
	if (harnessVersionCache.has(harnessId)) return harnessVersionCache.get(harnessId);
	let version = harnessId === "mock" ? "mock" : "unknown";
	for (const bin of HARNESS_VERSION_BINS[harnessId] ?? []) {
		try {
			const res = await execFileAsync(bin, ["--version"], { timeout: timeoutMs });
			const text = typeof res === "string" ? res : (res?.stdout ?? "");
			const first = String(text).split("\n")[0].trim();
			if (first) {
				version = first.slice(0, 120);
				break;
			}
		} catch {
			// Try the next binary; a missing CLI is "unknown", not fatal.
		}
	}
	const versions = { [harnessId]: version };
	harnessVersionCache.set(harnessId, versions);
	return versions;
}

/***
 * MARK: clearHarnessVersionCache
 * @description Test hook: drops the cached `--version` probes so each test
 *   observes a fresh probe.
 * @example clearHarnessVersionCache()
 ***/
export function clearHarnessVersionCache() {
	harnessVersionCache.clear();
}

/***
 * MARK: runnerHarnessIds
 * @description Normalized harness list for one Runner: the csv
 *   `harnessIds` when configured, else the singular primary `harnessId`.
 *   Tolerates hand-built configs (tests) that only set `harnessId`.
 * @example runnerHarnessIds({ harnessId: 'pi' }) => ['pi']
 * @param {Object} [config] - Normalized runner config.
 * @returns {string[]} Harness ids, primary first.
 ***/
export function runnerHarnessIds(config = {}) {
	const ids = Array.isArray(config.harnessIds)
		? config.harnessIds.map((h) => String(h ?? "").trim()).filter(Boolean)
		: [];
	if (ids.length > 0) return ids;
	const primary = String(config.harnessId ?? "").trim();
	return primary ? [primary] : [];
}

/***
 * MARK: AUTO_DETECTABLE_HARNESSES
 * @description Harness ids auto-detect considers, in stable advertise
 *   order. Only ids defaultLoadHarness can actually run; `mock` has no
 *   CLI so it never auto-detects (pass it manually with --manual).
 * @example AUTO_DETECTABLE_HARNESSES => ['pi', 'muse', 'antigravity', 'vibe']
 ***/
export const AUTO_DETECTABLE_HARNESSES = ["pi", "muse", "antigravity", "vibe"];

/***
 * MARK: detectAvailableHarnesses
 * @description Scans PATH for harness CLIs (default behaviour; --manual
 *   opts out). One entry per harness whose first binary resolves to an
 *   executable file. Pure sync scan so boot can fail fast before join.
 * @example detectAvailableHarnesses({ pathValue: '/usr/bin:/bin' }) => ['pi']
 * @param {Object} [opts] - Options.
 * @param {string} [opts.pathValue] - PATH to scan (defaults to process.env.PATH).
 * @param {string} [opts.pathDelimiter] - PATH separator (defaults to path.delimiter).
 * @param {Function} [opts.isExecutable] - (bin, dir) => boolean override (tests).
 * @returns {string[]} Detected harness ids in AUTO_DETECTABLE_HARNESSES order.
 ***/
export function detectAvailableHarnesses({ pathValue, pathDelimiter, isExecutable } = {}) {
	const pathStr = typeof pathValue === "string" ? pathValue : (process.env.PATH ?? "");
	const delimiter = typeof pathDelimiter === "string" ? pathDelimiter : path.delimiter;
	const dirs = String(pathStr)
		.split(delimiter)
		.map((d) => d.trim())
		.filter(Boolean);
	const check =
		typeof isExecutable === "function"
			? isExecutable
			: (bin, dir) => {
					try {
						fs.accessSync(path.join(dir, bin), fs.constants.X_OK);
						return true;
					} catch {
						return false;
					}
				};
	const found = [];
	for (const id of AUTO_DETECTABLE_HARNESSES) {
		const bins = HARNESS_VERSION_BINS[id] ?? [];
		let ok = false;
		for (const bin of bins) {
			for (const dir of dirs) {
				try {
					if (check(bin, dir)) {
						ok = true;
						break;
					}
				} catch {
					// Keep scanning; one bad dir never fails detection.
				}
			}
			if (ok) break;
		}
		if (ok) found.push(id);
	}
	return found;
}

/***
 * MARK: resolveHarnessConfig
 * @description Applies the auto-detect default to a loaded runner config.
 *   Manual configs (explicit harness ids, harnessAuto falsy) pass through
 *   untouched. Auto configs probe PATH, union any explicit non-auto pins,
 *   and mutate the config in place (harnessIds/harnessId). Empty detection
 *   throws fail-fast — the runner must never register a useless empty
 *   capability set.
 * @example resolveHarnessConfig({ harnessIds: [], harnessAuto: true }, { detected: ['pi'] }).harnessId => 'pi'
 * @param {Object} config - Normalized runner config (mutated).
 * @param {Object} [opts] - Options.
 * @param {string[]} [opts.detected] - Detected ids override (tests/installers).
 * @param {Object} [opts.detectOpts] - Forwarded to detectAvailableHarnesses.
 * @returns {Object} The same config object, resolved.
 ***/
export function resolveHarnessConfig(config = {}, { detected, detectOpts } = {}) {
	if (!config || !config.harnessAuto) return config;
	const seen = new Set();
	const out = [];
	const push = (id) => {
		const clean = String(id ?? "").trim();
		if (!clean || seen.has(clean)) return;
		seen.add(clean);
		out.push(clean);
	};
	const autoList = Array.isArray(detected) ? detected : detectAvailableHarnesses(detectOpts);
	for (const id of autoList) push(id);
	for (const id of runnerHarnessIds(config)) push(id);
	if (out.length === 0) {
		throw new Error(
			"Runner auto-detect found no harness CLIs (probed pi, muse, agy/antigravity, vibe on PATH); install one or re-run with --manual --harness NAME.",
		);
	}
	config.harnessIds = out;
	config.harnessId = out[0];
	config.harnessAuto = false;
	// Drop the stale missing-harness error so the boot check below passes.
	if (Array.isArray(config.errors)) {
		config.errors = config.errors.filter((e) => !/KAINBAIN_RUNNER_HARNESS/.test(String(e)));
	}
	return config;
}

/***
 * MARK: applyBackendPrompt
 * @description Retargets a backend-curated prompt to the prepared worktree:
 *   the backend curates with its own project cwd (it owns task/stage truth),
 *   so every occurrence of that cwd prefix is rewritten to the worktree the
 *   harness will actually run in. Empty prompt (old backend) stays empty so
 *   the caller falls back to its minimal prompt.
 * @example applyBackendPrompt({ prompt: 'see /repo/docs', backendCwd: '/repo', workdir: '/w' }) => 'see /w/docs'
 * @param {Object} opts - `{ prompt, backendCwd, workdir }`.
 * @returns {string} The retargeted prompt.
 ***/
export function applyBackendPrompt({ prompt, backendCwd, workdir } = {}) {
	const text = typeof prompt === "string" ? prompt : "";
	if (!text || !backendCwd || !workdir || backendCwd === workdir) return text;
	return text.split(backendCwd).join(workdir);
}

/***
 * MARK: startClaimRenewal
 * @description Renews the task claim on a cadence while a harness runs
 *   (D1): agent stages routinely outlive the claim TTL, and without
 *   renewal the hold lapses mid-stage — the task re-queues, the UI
 *   assignment vanishes, and the finisher reports STALE_EPOCH. Renewal
 *   is best-effort (a failure warns, the final complete surfaces
 *   staleness) and the timer is unref'd so it dies with the daemon —
 *   a dead Runner's hold still lapses.
 * @example const stop = startClaimRenewal({ client, logger, taskId: 't1', ... }); stop();
 * @param {Object} opts - Options (client, logger, taskId, projectId, executionId, epoch, intervalMs?).
 * @returns {Function} Call to stop the renewal timer.
 ***/
export function startClaimRenewal({
	client,
	logger,
	taskId,
	projectId,
	executionId,
	epoch,
	intervalMs = CLAIM_HEARTBEAT_MS,
	onTick = null,
}) {
	const fireTick = () => {
		try {
			if (typeof onTick === "function") onTick();
		} catch {
			// Liveness marking must never break lease renewal.
		}
	};
	const timer = setInterval(() => {
		client
			.claimHeartbeat({ taskId, projectId, executionId, epoch })
			.then(
				() => fireTick(),
				(err) => {
				logger.warn(`Claim renewal failed: ${err?.message || err}`);
				// The backend timed the stage out and released the hold:
				// stop propping it up. The harness run itself continues to
				// its natural finish, whose complete is then stale-rejected
				// by the lease fence — never reported as fresh work.
				if (err?.code === "STAGE_TIMEOUT") clearInterval(timer);
			});
	}, intervalMs);
	if (typeof timer.unref === "function") timer.unref();
	return () => clearInterval(timer);
}

/***
 * MARK: diskHeadroomMbFor
 * @description Measures free space on the filesystem holding the Runner
 *   work root (G4: R10 dispatch cut-off). Synchronous — one statfs call
 *   per heartbeat. Returns null when unmeasurable so the backend
 *   `DISK_LOW` check stays skipped rather than firing on bad data.
 * @example diskHeadroomMbFor('/tmp') => 12345
 * @param {string} workRoot - Runner work root (or any path on that fs).
 * @returns {number|null} Free megabytes, or null when unmeasurable.
 ***/
export function diskHeadroomMbFor(workRoot) {
	for (const candidate of [workRoot, process.cwd()]) {
		try {
			if (!candidate) continue;
			const st = fs.statfsSync(candidate);
			if (st && Number.isFinite(st.bavail) && Number.isFinite(st.bsize)) {
				return Math.floor((st.bavail * st.bsize) / (1024 * 1024));
			}
		} catch {
			// Try the next candidate; unmeasurable stays null.
		}
	}
	return null;
}

/***
 * MARK: defaultLoadHarness
 * @description Resolves a harness implementation by id for loopback runs.
 *   Anything HarnessSession-conforming works; only the ids below are
 *   wired (anything else fails fast naming what is supported).
 * @example const h = await defaultLoadHarness('mock')
 * @param {string} harnessId - Harness id (mock, pi, muse, antigravity, vibe).
 * @returns {Promise<Object>} Harness with `createSession`.
 ***/
export async function defaultLoadHarness(harnessId) {
	if (harnessId === "mock") {
		const { createMockHarness } = await import(
			"../api/agent/harnesses/mock/mockHarness.js"
		);
		return createMockHarness({ models: [] });
	}
	if (harnessId === "pi") {
		const { createPiHarness } = await import("../api/agent/harnesses/pi/piHarness.js");
		return createPiHarness({});
	}
	if (harnessId === "muse") {
		const { createMuseHarness } = await import(
			"../api/agent/harnesses/muse/museHarness.js"
		);
		return createMuseHarness({});
	}
	if (harnessId === "antigravity") {
		const { createAntigravityHarness } = await import(
			"../api/agent/harnesses/antigravity/agyHarness.js"
		);
		return createAntigravityHarness({});
	}
	if (harnessId === "vibe") {
		const { createVibeHarness } = await import(
			"../api/agent/harnesses/vibe/vibeHarness.js"
		);
		return createVibeHarness({});
	}
	throw new Error(`Unknown harness ${harnessId} (supported: mock, pi, muse, antigravity, vibe).`);
}

/***
 * MARK: discoveredModelsCache
 * @description Last model auto-discovery result, shared by every factsFor
 *   call until the next refresh. Seeded at boot, refreshed on the
 *   modelDiscoveryIntervalMs cadence (default 12h). The operator's explicit
 *   MODELS/MODEL list always wins (see resolveAdvertisedModels), so this
 *   cache only matters when nothing is pinned.
 ***/
let discoveredModelsCache = [];

/***
 * MARK: clearDiscoveredModelsCache
 * @description Test seam: resets the discovery cache between cases.
 ***/
export function clearDiscoveredModelsCache() {
	discoveredModelsCache = [];
}

/***
 * MARK: refreshDiscoveredModels
 * @description One discovery round: when the operator pinned no models and
 *   the `muse` harness is configured, asks the installed CLI for its model
 *   menu (muse serve model/list, box-local login, no keys leave the host)
 *   and caches the ids. Best-effort — failures keep the previous cache and

./runner/logEvents.js
---
import { redactDeepStrings } from "../shared/redactSecrets.js";

/**
 * MARK: structuredEventSender
 * @description Batches normalized agent session events for the backend
 *   `POST /tasks/:id/log-events` endpoint (structured log transport). The
 *   sender redacts every event before it leaves the Runner (defense in depth
 *   for locally-read secrets), caps oversized payloads, and degrades to
 *   legacy text frames: the first failed batch flips the sender to
 *   text-fallback mode, converts that batch to text, and all later events
 *   flow through the daemon's `onLog` path instead — so an old backend
 *   degrades to today's coarse text view instead of losing logs.
 *
 *   Pure batching over an injected client: no harness imports, no I/O of its
 *   own. The daemon owns the `onLog` gating via `isStructured()`.
 */

/***
 * MARK: MAX_EVENT_BYTES
 * @description Per-event JSON cap before transport. Oversized payloads (full
 *   file contents in a tool result) are truncated field-first, never dropped
 *   silently without the marker.
 * @example MAX_EVENT_BYTES => 65536
 ***/
export const MAX_EVENT_BYTES = 65536;

/***
 * MARK: sanitizeStructuredEvent
 * @description Makes one session event JSON-safe and transport-bounded:
 *   redacts secrets/PII (position- and shape-aware), drops functions and
 *   unserializable values via a JSON round-trip, and truncates oversized
 *   payload fields with a visible marker. Returns null when the event has no
 *   usable type or still exceeds the cap after truncation.
 * @example sanitizeStructuredEvent({ type: 'assistant_delta', delta: 'hi' }) => { type: 'assistant_delta', delta: 'hi' }
 * @param {Object} event - One normalized session event.
 * @param {number} [maxBytes] - Per-event JSON cap.
 * @returns {Object|null} The sanitized event, or null to skip it.
 ***/
export const sanitizeStructuredEvent = (event, maxBytes = MAX_EVENT_BYTES) => {
	if (!event || typeof event !== "object" || typeof event.type !== "string") {
		return null;
	}
	const cap = maxBytes > 0 ? maxBytes : MAX_EVENT_BYTES;
	let redacted;
	try {
		redacted = redactDeepStrings(event);
	} catch {
		return null;
	}
	const sizeOf = (value) => {
		try {
			return JSON.stringify(value)?.length ?? Infinity;
		} catch {
			return Infinity;
		}
	};
	if (sizeOf(redacted) <= cap) return redacted;
	// Truncate the large free-text payload fields first, keeping the event
	// envelope (type, toolName, meta) so the step stays visible.
	const truncated = { ...redacted };
	for (const field of ["result", "partialResult", "delta", "content", "text", "output"]) {
		if (typeof truncated[field] === "string" && truncated[field].length > 1000) {
			truncated[field] = `${truncated[field].slice(0, 1000)}…[truncated for transport]`;
		}
		if (sizeOf(truncated) <= cap) return truncated;
	}
	// Object-shaped payloads (e.g. result {content:[{text}]}) carry their
	// bulk in nested strings: truncate every long string in place (the
	// redacted clone is ours to mutate) before giving up on the event.
	const seen = new Set();
	const truncateDeep = (node) => {
		if (!node || typeof node !== "object" || seen.has(node)) return;
		// Note: Dates and RegExps cannot reach this walker (the redacted
		// clone converts them to strings), and they carry no enumerable
		// keys anyway, so there is deliberately no special case for them.
		seen.add(node);
		for (const key of Object.keys(node)) {
			// Never write __proto__: the redacted clone has none, and
			// assigning it would change the prototype instead of storing.
			if (key === "__proto__") continue;
			// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked payload
			const child = node[key];
			if (typeof child === "string" && child.length > 1000) {
				// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked payload
				node[key] = `${child.slice(0, 1000)}…[truncated for transport]`;
			} else {
				truncateDeep(child);
			}
		}
	};
	truncateDeep(truncated);
	if (sizeOf(truncated) <= cap) return truncated;
	return null;
};

/***
 * MARK: textForStructuredEvent
 * @description Legacy text derivation for one structured event — the same two
 *   shapes the pre-structured `onLog` path forwarded
 *   (`assistant_delta.delta`, `harness_log.text`). Returns null for
 *   tool/telemetry/permission/plan events, which have no legacy text form.
 * @example textForStructuredEvent({ type: 'assistant_delta', delta: 'hi' }) => 'hi'
 * @param {Object} event - One normalized session event.
 * @returns {string|null} The legacy text, or null when there is none.
 ***/
export const textForStructuredEvent = (event) => {
	if (!event || typeof event !== "object") return null;
	if (event.type === "assistant_delta" && typeof event.delta === "string") {
		return event.delta;
	}
	if (event.type === "harness_log" && typeof event.text === "string") {
		return event.text;
	}
	return null;
};

/***
 * MARK: createStructuredEventSender
 * @description Buffers sanitized session events and ships them as sequenced
 *   batches. Flushes on `batchSize`, on `flushMs` of quiet, on explicit
 *   `flush()`/`close()`, and immediately on run-closing events
 *   (`run_finished`, `run_error`) so the tail never waits for the timer.
 *   `flush()`/`close()` DRAIN: they resolve only once every queued event
 *   has been sent, including events that arrived while a batch was in
 *   flight (the caller can rely on the tail landing before it reports the
 *   stage complete). The first send failure flips to text-fallback
 *   permanently for this execution: the failed batch AND everything still
 *   queued convert to text via `onTextFallback`, and later events are left
 *   to the daemon's `onLog` path (`isStructured()` goes false).
 * @example const sender = createStructuredEventSender({ client, taskId: 't', projectId: 'p', executionId: 'e', epoch: 1, onTextFallback: () => {} })
 * @param {Object} opts - Options.
 * @param {Object} opts.client - Runner backend client with `logEvents`.
 * @param {string} opts.taskId - Task id.
 * @param {string} opts.projectId - Project id.
 * @param {string} opts.executionId - Lease execution id.
 * @param {number} opts.epoch - Lease epoch.
 * @param {Function} [opts.onTextFallback] - Called with legacy text per convertible event after the fallback flip.
 * @param {Object} [opts.logger] - Logger for send warnings.
 * @param {number} [opts.batchSize=25] - Events per batch.
 * @param {number} [opts.flushMs=500] - Quiet-ms before a partial batch ships.
 * @returns {Object} Sender with `queueEvent`, `flush`, `close`, `isStructured`.
 ***/
export const createStructuredEventSender = ({
	client,
	taskId,
	projectId,
	executionId,
	epoch,
	onTextFallback = () => {},
	logger = null,
	batchSize = 25,
	flushMs = 500,
}) => {
	let seq = 0;
	let pending = [];
	let structured = true;
	let timer = null;
	let inFlight = null;

	const warn = (message) => {
		try {
			if (logger && typeof logger.warn === "function") logger.warn(message);
		} catch {
			// Logging must never break the run.
		}
	};

	const clearTimer = () => {
		if (timer) {
			clearTimeout(timer);
			timer = null;
		}
	};

	const armTimer = () => {
		if (timer || flushMs <= 0) return;
		timer = setTimeout(() => {
			timer = null;
			flush().catch(() => {});
		}, flushMs);
		if (typeof timer.unref === "function") timer.unref();
	};

	const sendBatch = async (batch, batchSeq) => {
		await client.logEvents({
			taskId,
			projectId,
			executionId,
			epoch,
			seq: batchSeq,
			events: batch,
		});
	};

	const fallBack = (failedBatch, err) => {
		structured = false;
		clearTimer();
		// Convert everything not yet sent, not just the failed batch: events
		// queued while that batch was in flight were never transported
		// structured and must not vanish during the fallback transition.

		// structured and must not vanish during the fallback transition.
		const unsent = [...failedBatch, ...pending];
		pending = [];
		warn(
			`Structured log transport failed (${err?.message || err || "unknown error"}); falling back to text frames.`,
		);
		for (const event of unsent) {
			const text = textForStructuredEvent(event);
			if (text) {
				try {
					onTextFallback(text);
				} catch {
					// A throwing fallback must never break the run.
				}
			}
		}
	};

	const flush = async () => {
		// Drain loop, not a single pass: events queued while a batch is in
		// flight must ship too. close() relies on this — the trailing batch
		// has to be sent before the caller reports the stage complete.
		// Taking a batch (`pending` → local) is synchronous, so concurrent
		// flushes can never send the same events twice.
		for (;;) {
			if (!structured || pending.length === 0) return;
			if (inFlight) {
				await inFlight;
				continue;
			}
			const batch = pending;
			pending = [];
			clearTimer();
			const batchSeq = seq;
			seq += 1;
			inFlight = sendBatch(batch, batchSeq).catch((err) => {
				fallBack(batch, err);
			});
			try {
				await inFlight;
			} finally {
				inFlight = null;
			}
		}
	};

	const queueEvent = (event) => {
		if (!structured) return;
		const closesRun = event?.type === "run_finished" || event?.type === "run_error";
		const sanitized = sanitizeStructuredEvent(event);
		if (!sanitized) {
			// A dropped closing event must still flush what is already
			// queued: the tail must never wait for the timer just because
			// the final envelope was oversized or unusable.
			if (closesRun) flush().catch(() => {});
			return;
		}
		pending.push(sanitized);
		if (closesRun || pending.length >= Math.max(1, batchSize)) {
			flush().catch(() => {});
			return;
		}
		armTimer();
	};

	const close = async () => {
		clearTimer();
		await flush();
	};

	const isStructured = () => structured;

	return { queueEvent, flush, close, isStructured };
};

