		let j = i + 2;
		let depth = 1;
		while (j < len && depth > 0) {
			const ch = source[j];
			const next = source[j + 1];
			if (ch === "/" && next === "/") {
				let k = j + 2;
				while (k < len && source[k] !== "\n") k++;
				mask(j, k);
				j = k;
			} else if (ch === "/" && next === "*") {
				const end = source.indexOf("*/", j + 2);
				const k = end === -1 ? len : end + 2;
				mask(j, k);
				j = k;
			} else if (ch === "'" || ch === '"') {
				j = skipString(j);
			} else if (ch === "`") {
				j = skipTemplate(j);
			} else {
				if (ch === "{") depth++;
				else if (ch === "}") depth--;
				j++;
			}
		}
		return j;
	};
