	// `${}` interpolations as code. Returns the index after the closing
	// backtick (or end of input for an unterminated literal).
	const skipTemplate = (i) => {
		let j = i + 1;
		let segStart = j;
		while (j < len) {
			const ch = source[j];
			if (ch === "\\") j += 2;
			else if (ch === "`") {
				mask(segStart, j);
				mask(j, j + 1);
				return j + 1;
			} else if (ch === "$" && source[j + 1] === "{") {
				mask(segStart, j);
				j = skipInterpolation(j);
				segStart = j;
			} else j++;
		}
		if (segStart < len) mask(segStart, len);
		return len;
	};
	let i = 0;
	while (i < len) {
		const ch = source[i];
		const next = source[i + 1];
		if (ch === "/" && next === "/") {
			let j = i + 2;
			while (j < len && source[j] !== "\n") j++;
			mask(i, j);
			i = j;
		} else if (ch === "/" && next === "*") {
			const end = source.indexOf("*/", i + 2);
			const j = end === -1 ? len : end + 2;
			mask(i, j);
			i = j;
		} else if (ch === "'" || ch === '"') {
			i = skipString(i);
		} else if (ch === "`") {
			i = skipTemplate(i);
		} else {
			i++;
		}
	}
	return out.join("");
}

