	lines.push("Remediation:");
	lines.push("  1. Split each function into its own file named after the function");
	lines.push("     (e.g. api/work/buildFoo.js for function buildFoo).");
	lines.push("  2. Keep this file as a barrel re-export if callers need one entry point.");
	lines.push("  3. Do NOT add this file to scripts/allowlists/one-function-per-file.json:");
	lines.push("     that list is reserved for files that existed before this gate (q13).");
	lines.push("See: AGENTS-MAP.md §one-function-per-file, KB Code Standards §modularity.");
	lines.push("");
	lines.push("Reproduce locally: npm run check:one-function");
	return lines.join("\n");
}

function scanCounts() {
	const counts = {};
	for (const file of collectSourceFiles()) {
		const source = fs.readFileSync(path.join(REPO_ROOT, file), "utf8");
		counts[file] = topLevelFunctions(source);
	}
	return counts;
}

const invokedDirectly =
	process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
	const args = new Set(process.argv.slice(2));
	if (args.has("--write-allowlist")) {
		const counts = scanCounts();
		const listed = Object.entries(counts)
			.filter(([, names]) => names.length >= 2)
			.map(([file]) => file)
			.sort();
		fs.mkdirSync(path.dirname(ALLOWLIST_PATH), { recursive: true });
		fs.writeFileSync(ALLOWLIST_PATH, `${JSON.stringify(listed, null, 2)}\n`);
		console.log(`allowlist: wrote ${listed.length} files to ${path.relative(REPO_ROOT, ALLOWLIST_PATH)}`);
	} else {
		const counts = scanCounts();
		const allowlist = readAllowlist();
		const newlyAdded = listNewlyAdded();
		if (args.has("--report")) {
			const multi = Object.entries(counts).filter(([, names]) => names.length >= 2);
			console.log(`one-function-per-file report: ${multi.length} multi-function files`);
			for (const [file, names] of multi) {
				const tag = allowlist.includes(file) ? "allowlisted" : "UNLISTED";
				console.log(`  ${tag} ${file} (${names.length}): ${names.join(", ")}`);
			}
			const { stale } = checkFiles(counts, allowlist, newlyAdded);
			if (stale.length > 0) {
				console.log(`stale allowlist entries (now <= 1 function, may prune): ${stale.join(", ")}`);
			}
		}
		const { failures } = checkFiles(counts, allowlist, newlyAdded);
		if (failures.length > 0) {
			console.error(formatFailure(failures));
			process.exit(1);
		}
		console.log(
			`one-function-per-file: PASS (${Object.keys(counts).length} files scanned, ${allowlist.length} grandfathered)`,
		);
	}
}

import { RUNNER_PROTOCOL } from "../runnerRegistry.js";
import { runnerApiCompatible } from "./runnerApiCompat.js";
import { operatorConfigVerdict } from "./operatorConfigVerdict.js";
import { stageRunnerPolicyVerdict } from "../../../shared/stageRunnerPolicy.js";

/***
 * MARK: effectiveRunnerModels
 * @description The model ids one Runner may serve: the operator-owned
 *   `availableModels` allowlist when set (System Settings › Runners ›
 *   Models — it replaces the advertised list so an under-reporting Runner
 *   can serve declared models), otherwise the Runner-advertised
 *   capabilities list. Single enforcement point shared by the dispatch
 *   gate below and the fleet model catalogue, so the two can never drift.
 * @example effectiveRunnerModels({ capabilities: { models: ['m1'] } }) => ['m1']
 * @param {Object} [record={}] - Runner record.
 * @returns {string[]} Effective model ids (possibly empty).
 ***/
export function effectiveRunnerModels(record = {}) {
	const override = record?.operatorConfig?.availableModels;
	if (Array.isArray(override)) return override;
	const caps = record?.capabilities && typeof record.capabilities === "object" ? record.capabilities : {};
	return Array.isArray(caps.models) ? caps.models : [];
}

/***
 * MARK: claimEligibleRunner
 * @description Whether one Runner registration can take ANY work right now:
 *   active status and not paused — the same two gates `runnerMatches`
 *   applies before per-task requirements. The fleet model catalogue counts
 *   only eligible Runners, so "available on N runners" always names
 *   Runners that could actually claim.
 * @example claimEligibleRunner({ status: 'active', paused: false }) => true
 * @param {Object} [record={}] - Runner record.
 * @returns {boolean} Eligibility.
 ***/
export function claimEligibleRunner(record = {}) {
	return record?.status === "active" && record?.paused !== true;
}

/***
 * MARK: runnerMatches
 * @description Decides whether one Runner registration can take a task with
 *   the given requirements: active status, not paused, fresh heartbeat
 *   (staleness expiry), v1 protocol, runnable flag, harness id, model
 *   offering, tier membership, and disk headroom floor. Returns
 *   `{ ok, reason }` — the
 *   reason code is loud by design (step-6 NO_CAPABLE_RUNNER diagnostics
 *   and the monitor surface distinguish "no runners" from "runners that
 *   cannot take this job"). Alias requirements always miss here; WP-3.2
 *   resolves them centrally first. The last two gates are owner settings:
 *   the Runner's own `operatorConfig` first, then the stage's
 *   `runnerPolicy` (`RUNNER_NOT_ALLOWED` / `RUNNER_BLOCKED`) — owner
 *   settings keep a stable order so combined refusals always report the
 *   same reason.
 * @example runnerMatches(record, { harness: 'pi', tier: 'T1' }) => { ok: true, reason: 'MATCH' }
 * @param {Object} record - Registry record (`status`, `facts`, `lastSeenAt`, `capabilities`, plus the operator-owned `operatorConfig` the Runners settings screen persists).
 * @param {Object} req - Task requirements from `taskRequirements`.
 * @param {Object} [opts] - `{ now, staleAfterMs, minDiskHeadroomMb, projectId }` (`projectId` is the candidate's project, needed for the operator project-scope check; a scoped Runner with no project id on the candidate misses loudly instead of guessing).
 * @returns {Object} `{ ok, reason }`.
 ***/
export function runnerMatches(record = {}, req = {}, opts = {}) {
	const now = typeof opts.now === "number" ? opts.now : Date.now();
	const staleAfterMs =
		typeof opts.staleAfterMs === "number" && opts.staleAfterMs > 0
			? opts.staleAfterMs
			: 60000;
	const minDisk =
		typeof opts.minDiskHeadroomMb === "number" && opts.minDiskHeadroomMb >= 0
			? opts.minDiskHeadroomMb
			: 100;
	if (record.status !== "active") return { ok: false, reason: "NOT_ACTIVE" };
	if (record.paused === true) return { ok: false, reason: "PAUSED" };
	const seen = Date.parse(record.lastSeenAt || "");
	if (!Number.isFinite(seen) || now - seen > staleAfterMs) {
		return { ok: false, reason: "STALE_HEARTBEAT" };
	}
	const caps = record.capabilities || {};
	if (caps.runnable === false) return { ok: false, reason: "NOT_RUNNABLE" };
	const protocol =
		caps.versions?.protocol || record.facts?.versions?.protocol;

import { parseModelKey } from './modelKeys.js';

/***
 * MARK: fleet model options
 * @description Turns fleet catalogue availability (`fleetCountsById`: exact
 *   advertised model ids) into picker options for harnesses the backend
 *   catalogue leaves empty. The backend host can only list models ITS
 *   credentials unlock; the fleet serves more (e.g. a runner's
 *   auto-discovered `muse` menu). Options carry the EXACT advertised id as
 *   their key — dispatch matches requirements against advertised ids
 *   verbatim, so an exact id is a guaranteed matchable selection.
 *
 *   Attribution is strict for harness-scoped ids (`h::p::m` only ever
 *   appears under `h`, so a `pi`-grammar id can never be picked for
 *   `muse`); legacy `provider::id` and bare ids name no harness and appear
 *   under every section the fleet serves them on. Ids already present by
 *   value are never duplicated. Unknown or malformed ids are skipped.
 ***/

/***
 * MARK: fleetModelsForHarness
 * @description Synthesizes fleet-served model entries for one harness
 *   section: `{ key, id, provider, name, fleet: true }`. `key` is the exact
 *   advertised id (the stored selection value). Only meaningful when fleet
 *   data loaded — pass `undefined` counts and it returns `[]` (badge-free
 *   and option-free, never mislead).
 * @example fleetModelsForHarness('muse', { 'muse::meta::muse-spark-1.3': { runnerCount: 1 } })
 *   => [{ key: 'muse::meta::muse-spark-1.3', id: 'muse-spark-1.3', provider: 'meta', name: 'muse-spark-1.3', fleet: true }]
 * @param {string} harnessId - Catalogue harness section being rendered.
 * @param {Object} [fleetCounts] - Fleet map from `fleetCountsById`.
 * @returns {Array<Object>} Synthesized model entries (possibly empty).
 ***/
export function fleetModelsForHarness(harnessId, fleetCounts) {
  const hid = typeof harnessId === 'string' ? harnessId.trim() : '';
  if (!hid || !fleetCounts || typeof fleetCounts !== 'object') return [];
  const out = [];
  for (const exactId of Object.keys(fleetCounts)) {
    const id = typeof exactId === 'string' ? exactId.trim() : '';
    if (!id) continue;
    let parsed = null;
    try {
      parsed = parseModelKey(id);
    } catch {
      continue;
    }
    if (!parsed) continue;
    // Section gate: the entry's serving harnesses (empty = unknown, keep
    // lenient). An operator allowlist can advertise ids for harnesses the
    // runner does not offer — those sections must not offer the id, or
    // dispatch would match a model no serving runner can run there.
    // eslint-disable-next-line security/detect-object-injection -- exactId is a catalogue model id, not user input
    const entry = fleetCounts[exactId];
    const serving =
      entry && typeof entry === 'object' && Array.isArray(entry.harnesses) ? entry.harnesses : [];
    if (serving.length > 0 && !serving.includes(hid)) continue;
    if (parsed.form === 'harness' || parsed.form === 'harnessReasoning') {
      // Harness-scoped ids additionally name their section: strict match.
      if (parsed.harness !== hid) continue;
      out.push({
        key: id,
        id: parsed.form === 'harnessReasoning' ? `${parsed.id}::${parsed.reasoning}` : parsed.id,
        provider: parsed.provider,
        name: parsed.id,
        fleet: true,
      });
    } else if (parsed.form === 'provider') {
      out.push({ key: id, id: parsed.id, provider: parsed.provider, name: parsed.id, fleet: true });
    } else if (parsed.form === 'bare') {
      out.push({ key: id, id: parsed.id, provider: '', name: parsed.id, fleet: true });
    }
  }
  return out;
}

/***
 * MARK: fleetServesHarness
 * @description Whether the loaded fleet serves any model attributable to
 *   one harness section: a strict harness-scoped id for it, or a legacy /
 *   bare id (attributable everywhere). Drives the fleet-aware `none`-gate —
 *   a `none` harness the fleet serves behaves as `list` in fleet-executed
 *   pickers. Unloaded fleet data (`undefined`) never serves.
 * @example fleetServesHarness('muse', { 'muse::meta::m': {} }) => true
 * @param {string} harnessId - Catalogue harness section being rendered.
 * @param {Object} [fleetCounts] - Fleet map from `fleetCountsById`.
 * @returns {boolean} True when at least one fleet id belongs in the section.
 ***/
export function fleetServesHarness(harnessId, fleetCounts) {
  return fleetModelsForHarness(harnessId, fleetCounts).length > 0;
}

/***
 * MARK: withFleetModels
 * @description Merges synthesized fleet entries into one harness section's
 *   backend model list, skipping ids already present by option value so
 *   backend entries (with their richer labels) always win ties.
 * @example withFleetModels([{ key: 'a', id: 'a' }], 'h', { b: {} })
 * @param {Array<Object>} modelsForHarness - Backend catalogue models.
 * @param {string} harnessId - Catalogue harness section being rendered.
 * @param {Object} [fleetCounts] - Fleet map from `fleetCountsById`.
 * @returns {Array<Object>} Merged model list.
 ***/
export function withFleetModels(modelsForHarness, harnessId, fleetCounts) {
  const base = Array.isArray(modelsForHarness) ? modelsForHarness : [];
  if (!fleetCounts || typeof fleetCounts !== 'object') return base;
  const seen = new Set(
    base.map((m) => m?.key || (m?.provider ? `${m.provider}::${m.id}` : m?.id)),
  );
  const extra = fleetModelsForHarness(harnessId, fleetCounts).filter((m) => !seen.has(m.key));
  return extra.length > 0 ? [...base, ...extra] : base;
}

/***
 * MARK: effectiveModelSelection
 * @description The model-selection mode one picker section actually offers:
 *   backend `list` stays `list`; a backend `none` the fleet serves behaves
 *   as `list` in fleet-executed pickers (the fleet runs the choice). Every
 *   other mode passes through; backend-executed pickers (no fleet data)
 *   always see the backend mode.
 * @example effectiveModelSelection('none', 'muse', { 'muse::meta::m': {} }) => 'list'
 * @param {string} backendSelection - Catalogue `modelSelection` (`'list'`/`'none'`).
=== useFleetModelCatalog ===
import { useCallback, useEffect, useState } from 'react';
import { api } from '../services/api';

/***
 * MARK: fleetCountsById
 * @description Indexes a fleet catalogue payload by model id for option
 *   badges: `{ [id]: { runnerCount, runnerIds, harnesses, tiers } }`.
 *   Malformed entries never crash a picker — they are skipped.
 * @example fleetCountsById({ models: [{ id: 'm', runnerCount: 2, runnerIds: ['r1', 'r2'] }] })
 *   => { m: { runnerCount: 2, runnerIds: ['r1', 'r2'], harnesses: [], tiers: [] } }
 * @param {Object} [payload] - `/runners/models/catalogue` response.
 * @returns {Object} Id-keyed availability map.
 ***/
export function fleetCountsById(payload) {
  const map = {};
  const list = Array.isArray(payload?.models) ? payload.models : [];
  for (const entry of list) {
    const id = typeof entry?.id === 'string' ? entry.id.trim() : '';
    if (!id || Object.hasOwn(map, id)) continue;
    map[id] = {
      runnerCount: typeof entry.runnerCount === 'number' ? entry.runnerCount : 0,
      runnerIds: Array.isArray(entry.runnerIds)
        ? entry.runnerIds.filter((r) => typeof r === 'string')
        : [],
      harnesses: Array.isArray(entry.harnesses)
        ? entry.harnesses.filter((h) => typeof h === 'string')
        : [],
      tiers: Array.isArray(entry.tiers)
        ? entry.tiers.filter((t) => typeof t === 'string')
        : [],
    };
  }
  return map;
}

/***
 * MARK: useFleetModelCatalog
 * @description Fetches the fleet model catalogue (derived live from Runner
 *   registrations) once on mount: per-model runner availability for the
 *   stage, default, and alias pickers. No client cache — the backend
 *   derives it per request, so joins, leaves, and allowlist edits reflect
 *   on the next mount or manual `refresh()`. Failures resolve to an empty
 *   map (pickers render badge-free, never mislead).
 * @example const { counts, loading, loaded, refresh } = useFleetModelCatalog();
 * @param {Object} [opts]
 * @param {boolean} [opts.enabled=true] - When false, no request until it flips true.
 * @returns {{counts: Object, loading: boolean, loaded: boolean, refresh: Function}}
 ***/
export function useFleetModelCatalog({ enabled = true } = {}) {
  const [counts, setCounts] = useState({});
  // True only after a catalogue fetch succeeds: pickers gate badges on this
  // (not on `counts` being non-empty) so a failed fetch — or a backend
  // without the endpoint — renders badge-free instead of "No runners".
  const [loaded, setLoaded] = useState(false);
  const [loading, setLoading] = useState(
    () => enabled && typeof api.getFleetModelCatalog === 'function',
  );

  useEffect(() => {
    if (!enabled || typeof api.getFleetModelCatalog !== 'function') {
      return undefined;
    }
    let isMounted = true;
    api
      .getFleetModelCatalog()
      .then((res) => {
        if (!isMounted) return;
        setCounts(fleetCountsById(res));
        setLoaded(true);
      })
      .catch(() => {
        if (isMounted) setCounts({});
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });
    return () => {
      isMounted = false;
    };
  }, [enabled]);

  const refresh = useCallback(async () => {
    if (typeof api.getFleetModelCatalog !== 'function') return;
    try {
      const res = await api.getFleetModelCatalog();
      setCounts(fleetCountsById(res));
      setLoaded(true);
    } catch {
      // Keep the current map; a refresh failure never downgrades `loaded`.
    }
  }, []);

  return { counts, loading, loaded, refresh };
}

// Domain: Watching the Work — task progress entries and their feeds.
import { config } from "../config.js";
import { redactDeepStrings, redactSecretsText } from "../../shared/redactSecrets.js";
/***
 * MARK: _logEntryKindFromText
 * @description Maps a rendered log chunk to its structured entry kind and
 *   feed using the shared tag grammar. Untagged text is assistant narrative.
 * @example _logEntryKindFromText('[TOOL] bash(…)') => { kind: 'tool', feed: 'tools' }
 * @param {string} text
 * @returns {{kind: string, feed: string}}
 ***/
function _logEntryKindFromText(text) {
	const raw = String(text);
	const lines = raw.split("\n");
	const firstLine = lines[0] || "";
	if (/^\[(ERROR|FAIL|STDERR)\]/i.test(firstLine))
		return { kind: "error", feed: "main" };
	const checkLine = /^\[STDOUT\]/i.test(firstLine) && lines.length > 1 ? lines[1] : firstLine;
	if (/^\[(TOOL|RESULT)\]/.test(checkLine))
		return { kind: "tool", feed: "tools" };
	if (/^\[THINKING\]/.test(checkLine))
		return { kind: "thinking", feed: "thinking" };
	if (/^\[(ERROR|FAIL|STDERR)\]/.test(checkLine))
		return { kind: "error", feed: "main" };
	if (/^\[(INFO|SYSTEM|GIT|CI\/CMD|CI|HUMAN|WARN)\]/.test(checkLine)) {
		return { kind: "system", feed: "main" };
	}
	if (/^\[AGENT\]/.test(checkLine)) return { kind: "assistant", feed: "main" };
	// Runner frames carry an inline `[runner <id>]` prefix (ingested over
	// the wire). They get their own kind so the log viewer can tag and
	// filter them per runner instead of lumping them into assistant output.
	if (/^\[runner[ \]]/i.test(checkLine)) return { kind: "runner", feed: "main" };
	// Untagged text is assistant narrative (block text from the agent streamer).
	return { kind: "assistant", feed: "main" };
}

/** Monotonic counter for synthesized log entry ids (never Date.now() so
 *  same-millisecond entries cannot collide). */
let _logEntryIdCounter = 0;

/***
 * MARK: _synthesizedLogEntry
 * @description Wraps a rendered log chunk as a structured log entry so the
 *   UI has one uniform shape for every log source (agent streamer entries
 *   and system/GIT/CI lines alike).
 * @example _synthesizedLogEntry('[GIT] Switched to main') => { kind: 'system', text: '…', … }
 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`).
 * @returns {Object} A structured log entry.
 ***/
function _synthesizedLogEntry(chunk, meta = {}) {
	_logEntryIdCounter += 1;
	const { kind, feed } = _logEntryKindFromText(chunk);
	// Only a plain bag spreads into meta: exotic inputs (strings, Dates,
	// arrays) degrade to {} instead of scattering characters into the entry.
	const cleanedMeta = redactDeepStrings(meta || {});
	const metaBag =
		cleanedMeta && typeof cleanedMeta === "object" && !Array.isArray(cleanedMeta)
			? cleanedMeta
			: {};
	return {
		id: `log-${_logEntryIdCounter}`,
		ts: new Date().toISOString(),
		feed,
		feeds: [feed],
		kind,
		turn: null,
		// Redacted at synthesis so command output, git lines, and runner
		// text frames can never store secrets or PII. Clean text passes
		// through byte-identical.
		text: redactSecretsText(String(chunk)),
		meta: { source: "process-log", ...metaBag },
	};
}

/***
 * MARK: _capLogEntries
 * @description Keeps at most `config.logEntriesMaxCount` entries on a task,
 *   dropping the oldest and recording the eviction under a single updating
 *   marker entry (mirrors the streamer's eviction behaviour).
 * @example _capLogEntries(task)
 * @param {Object} task
 * @returns {void}
 ***/
function _capLogEntries(task) {
	const max = config.logEntriesMaxCount;
	if (!Array.isArray(task.logEntries) || task.logEntries.length <= max) return;
	const existingMarker = task.logEntries[0];
	const hasMarker = existingMarker?.meta?.evictedCount !== undefined;
	// Reserve one slot for the marker so the cap holds after it is unshifted.
	const keepTarget = hasMarker ? max : max - 1;
	const overflow = task.logEntries.length - keepTarget;
	if (overflow <= 0) return;
	task.logEntries.splice(hasMarker ? 1 : 0, overflow);
	const markerText = `[INFO] (${overflow} earlier log entries evicted)`;
	if (hasMarker) {
		const previousCount = existingMarker.meta.evictedCount + overflow;
		existingMarker.text = `[INFO] (${previousCount} earlier log entries evicted)`;
		existingMarker.meta = { evictedCount: previousCount };
	} else {
		_logEntryIdCounter += 1;
		task.logEntries.unshift({
			id: `log-${_logEntryIdCounter}`,
			ts: new Date().toISOString(),
			feed: "main",
			feeds: ["main"],
			kind: "system",
			turn: null,
			text: markerText,
			meta: { evictedCount: overflow },
		});
	}
}

/***
 * MARK: parseLegacyProcessLogText
 * @description Parses legacy rendered process-log text (line-based tag
 *   grammar) into structured entries (blank lines dropped, consecutive
 *   duplicates de-duped) so tasks predating the structured-entries era still
 *   serve feeds. Shared by the markdown legacy-section synthesis
 *   (`parseTaskMarkdown`) and the in-memory feed fallback below — it is a
 *   read-only migration path, never a second storage format.
 * @example parseLegacyProcessLogText('[INFO] a\n[INFO] a') => [entry('[INFO] a')]
 * @param {string} text
 * @returns {Array<Object>} Structured log entries.
 ***/
export function parseLegacyProcessLogText(text) {
	const source = typeof text === "string" ? text : "";
	if (!source.trim()) return [];
	const parsed = [];
	for (const line of source.split("\n")) {
		if (!line.trim()) continue;
		if (parsed.length > 0 && parsed[parsed.length - 1].text === line) continue;
		parsed.push(_synthesizedLogEntry(line));
	}
	return parsed;
}

/***
 * MARK: renderLogEntriesText
 * @description The ONE shared renderer from structured log entries to legacy
 *   tag-grammar text — every text view is derived here at read time, never
 *   stored. With a `feed` option only that feed's entries render; without
 *   one, the combined main+tools narrative renders (thinking entries stay
 *   out, mirroring the streamer's combined view).
 * @example renderLogEntriesText(entries) => "[AGENT] reasoning…\n[TOOL] bash(…)"
 * @example renderLogEntriesText(entries, { feed: 'tools' }) => "[TOOL] bash(…)"
 * @param {Array<Object>} entries
 * @param {{ feed?: string }} [opts]
 * @returns {string}
 ***/
export function renderLogEntriesText(entries, { feed } = {}) {
	const selected = (Array.isArray(entries) ? entries : []).filter((entry) => {
		if (!entry) return false;
		const placed = Array.isArray(entry.feeds) ? entry.feeds : [entry.feed];
		if (feed) return placed.includes(feed);
		return placed.includes("main") || placed.includes("tools");
	});
	return selected.map((entry) => entry.text).join("\n");
}

/***
 * MARK: _logEntriesForFeed
 * @description Collects a task's entries placed on one feed (main/thinking/
 *   tools), bounded to `config.logEntriesMaxCount`. Structured entries are
 *   the single storage path; the legacy-text fallback only exists for tasks
 *   still carrying a pre-migration `processLogs` string (read-only).
 * @example _logEntriesForFeed(task, 'thinking') => [thinkingEntry, …]
 * @param {Object} task
 * @param {string} feed
 * @returns {Array<Object>} The feed's entries, oldest first.
 ***/
export function _logEntriesForFeed(task, feed) {
	const structured = Array.isArray(task?.logEntries)
		? task.logEntries.filter(Boolean)
		: [];
	const all =
		structured.length > 0
			? structured
			: parseLegacyProcessLogText(task?.processLogs);
	const matching = all.filter((entry) =>
		(Array.isArray(entry.feeds) ? entry.feeds : [entry.feed]).includes(feed),
	);
	const capped = { logEntries: matching };
	_capLogEntries(capped);
	return capped.logEntries;
}

/***
 * MARK: _appendLogEntries
 * @description Appends structured log entries to task.logEntries, capping the
 *   array to `config.logEntriesMaxCount`.
 * @example _appendLogEntries(task, streamer.snapshot().entries)
 * @param {Object} task
 * @param {Array<Object>} newEntries
 * @returns {void}
 ***/
export function _appendLogEntries(task, newEntries) {
	if (!task || !Array.isArray(newEntries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	for (const entry of newEntries) {
		if (entry) task.logEntries.push(entry);
	}
	_capLogEntries(task);
}

/***
 * MARK: _replaceLogEntries
 * @description Replaces the log entries accumulated for one stage run (the
