function handlePlanUpdated(event) {
	const steps = Array.isArray(event.steps) ? event.steps : [];
	return [
		appendEntry({
			kind: "plan",
			feeds: ["main"],
			text: summarizePlan(event),
			meta: { steps },
		}),
	];
}

